pydatetimeconverterBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "pydatetimeconverterBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "ClinicoPathPj",
                name = "pydatetimeconverter",
                version = c(0,3,48),
                options = options,
                results = pydatetimeconverterResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'none')
        }))

#' DateTime Converter (Python UTC Core)
#'
#' 
#' @param data .
#' @param datetime_var .
#' @param datetime_format .
#' @param preview_rows .
#' @param extract_year .
#' @param extract_month .
#' @param extract_monthname .
#' @param extract_day .
#' @param extract_hour .
#' @param extract_minute .
#' @param extract_second .
#' @param extract_dayname .
#' @param extract_weeknum .
#' @param extract_quarter .
#' @param extract_dayofyear .
#' @param show_quality_metrics .
#' @param show_summary .
#' @param show_explanations .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$quality} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$preview} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$report} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$about} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$corrected_datetime_numeric} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$corrected_datetime_char} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$year_out} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$month_out} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$monthname_out} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$day_out} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$hour_out} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$minute_out} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$second_out} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$dayname_out} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$weeknum_out} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$quarter_out} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$dayofyear_out} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$quality$asDF}
#'
#' \code{as.data.frame(results$quality)}
#'
#' @export
pydatetimeconverter <- function(
    data,
    datetime_var = NULL,
    datetime_format = "ymd",
    preview_rows = 20,
    extract_year = FALSE,
    extract_month = FALSE,
    extract_monthname = FALSE,
    extract_day = FALSE,
    extract_hour = FALSE,
    extract_minute = FALSE,
    extract_second = FALSE,
    extract_dayname = FALSE,
    extract_weeknum = FALSE,
    extract_quarter = FALSE,
    extract_dayofyear = FALSE,
    show_quality_metrics = FALSE,
    show_summary = FALSE,
    show_explanations = FALSE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pydatetimeconverter requires jmvcore to be installed (restart may be required)")

    if ( ! missing(datetime_var)) datetime_var <- jmvcore::resolveQuo(jmvcore::enquo(datetime_var))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(datetime_var), datetime_var, NULL))


    options <- pydatetimeconverterOptions$new(
        datetime_var = datetime_var,
        datetime_format = datetime_format,
        preview_rows = preview_rows,
        extract_year = extract_year,
        extract_month = extract_month,
        extract_monthname = extract_monthname,
        extract_day = extract_day,
        extract_hour = extract_hour,
        extract_minute = extract_minute,
        extract_second = extract_second,
        extract_dayname = extract_dayname,
        extract_weeknum = extract_weeknum,
        extract_quarter = extract_quarter,
        extract_dayofyear = extract_dayofyear,
        show_quality_metrics = show_quality_metrics,
        show_summary = show_summary,
        show_explanations = show_explanations,
        showConsole = showConsole)

    analysis <- pydatetimeconverterClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

